try:
    df_vendors = pd.read_excel('vendors.xlsx')
    print(df_vendors.columns.tolist())
    print(df_vendors.head().to_string())
except Exception as e:
    print(e)

print("\n--- INVOICE PDF (PAGE 1) ---")
try:
    with pdfplumber.open('invoices.pdf') as pdf:
